// BlueGreen Ventures re-matched to the new mandate (checked on bluegreen.vc 2026-09-07).
// Deal Tracker has a BlueGreen row but records ZERO deals shared, so nothing is excluded on that basis.
const INVESTOR = 'BlueGreen Ventures';
const EMAIL = 'anup@bluegreen.vc';
const DATA = [["Appli","Akansha",100,"2026-09-08"],["Body & Beyond","Aditya",100,"2026-09-08"],["CLIKD","Aditya",100,"2026-09-09"],["Caffena Coffee","Aditya",100,"2026-09-09"],["EkoSight","Chaman",100,"2026-09-10"],["Ela Greens","Chaman",100,"2026-09-10"],["HYRGPT","Akansha",100,"2026-09-11"],["LUSTR","Aditya",100,"2026-09-11"],["Luxova","Aditya",100,"2026-09-14"],["My Soul","Aditya",100,"2026-09-14"],["Nexcore","Akansha",100,"2026-09-15"],["Orbis Lives","Chaman",100,"2026-09-15"],["RECEX","Akansha",100,"2026-09-16"],["Sahaj","Shradha",100,"2026-09-16"],["Sugar's Daddy","Aditya",100,"2026-09-17"],["VOLD Energy","Aditya",100,"2026-09-17"],["YUNO","Aditya",100,"2026-09-18"],["bezgoFresh","Chaman",100,"2026-09-18"],["Doffair","Chaman",88,"2026-09-21"],["Indie Stori","Aditya",88,"2026-09-21"]];

function s(v) { return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

let maxN = 0;
for (const r of rows) {
  const id = s(r.deal_id);
  if (id.charAt(0) === 'D') { const n = parseInt(id.slice(1), 10); if (!isNaN(n) && n > maxN) { maxN = n; } }
}
if (maxN === 0) { throw new Error('ABORT: could not determine max deal_id'); }

const seen = {};
for (const r of rows) { seen[s(r.startup).toLowerCase() + '||' + s(r.investor).toLowerCase()] = true; }

const out = [];
let n = maxN, skipped = 0;
for (const d of DATA) {
  const startup = d[0], owner = d[1], score = d[2], due = d[3];
  if (seen[startup.toLowerCase() + '||' + INVESTOR.toLowerCase()]) { skipped++; continue; }
  n++;
  let pad = String(n);
  while (pad.length < 5) { pad = '0' + pad; }
  out.push({ json: {
    deal_id: 'D' + pad,
    startup: startup,
    owner: owner,
    investor: INVESTOR,
    email: EMAIL,
    cc: '',
    priority: score,
    deal_shared: 'No',
    next_action: 'Initial',
    next_due: due,
    notes: (score >= 85 ? 'Very High' : 'High') + ' match (' + score + ') - re-matched to new BlueGreen mandate 2026-09-07'
  }});
}
if (out.length === 0) { throw new Error('ABORT: 0 new rows (skipped ' + skipped + ' as existing)'); }
if (out.length > 20) { throw new Error('ABORT: ' + out.length + ' exceeds guard of 20'); }
return out;
